package app.still.planner;
import android.content.*;import android.database.Cursor;import android.database.sqlite.*;import org.json.*;
public final class Store extends SQLiteOpenHelper {
 public static final Object LOCK=new Object();
 public Store(Context c){super(c,"still.db",null,1);}
 public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE snapshot (part INTEGER PRIMARY KEY, body TEXT NOT NULL)");d.execSQL("CREATE TABLE objects (id TEXT PRIMARY KEY, kind TEXT NOT NULL, title TEXT, createdAt TEXT, updatedAt TEXT)");d.execSQL("CREATE INDEX objects_kind ON objects(kind)");d.execSQL("CREATE VIRTUAL TABLE search_index USING fts4(id,kind,content)");}
 public void onUpgrade(SQLiteDatabase d,int o,int n){}
 public String load(){synchronized(LOCK){return readSnapshot();}}
 private String readSnapshot(){StringBuilder b=new StringBuilder();Cursor c=getReadableDatabase().rawQuery("SELECT body FROM snapshot ORDER BY part",null);try{while(c.moveToNext())b.append(c.getString(0));}finally{c.close();}return b.toString();}
 public void save(String raw)throws Exception{synchronized(LOCK){writeSnapshot(raw);}}
 public String saveFromWeb(String raw)throws Exception{synchronized(LOCK){JSONObject incoming=new JSONObject(raw);String current=load();boolean merged=TimerState.mergeNativeTimer(incoming,current.isEmpty()?null:new JSONObject(current));save(incoming.toString());return merged?TimerState.envelope(incoming).toString():"ok";}}
 private void writeSnapshot(String raw)throws Exception{JSONObject root=new JSONObject(raw);if(root.optInt("version")!=1||!root.has("preferences"))throw new Exception("Unsupported data");SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{db.delete("snapshot",null,null);int part=0;for(int i=0;i<raw.length();){int end=Math.min(i+200000,raw.length());if(end<raw.length()&&Character.isHighSurrogate(raw.charAt(end-1)))end--;ContentValues v=new ContentValues();v.put("part",part++);v.put("body",raw.substring(i,end));db.insertOrThrow("snapshot",null,v);i=end;}db.delete("objects",null,null);db.delete("search_index",null,null);for(String kind:new String[]{"boards","tasks","habits","notes","focusSessions"}){JSONArray arr=root.getJSONArray(kind);for(int i=0;i<arr.length();i++){JSONObject x=arr.getJSONObject(i);String title=x.optString("title",x.optString("name",""));ContentValues v=new ContentValues();v.put("id",x.getString("id"));v.put("kind",kind);v.put("title",title);v.put("createdAt",x.optString("createdAt"));v.put("updatedAt",x.optString("updatedAt"));db.insertOrThrow("objects",null,v);ContentValues f=new ContentValues();f.put("id",x.getString("id"));f.put("kind",kind);f.put("content",title+" "+x.optString("description")+" "+x.optString("notes")+" "+x.optString("body")+" "+x.optString("tags"));db.insertOrThrow("search_index",null,f);}}db.setTransactionSuccessful();}finally{db.endTransaction();}}
}
